"use strict";(self.webpackChunksmart_barcode_scan_and_ordering_doc=self.webpackChunksmart_barcode_scan_and_ordering_doc||[]).push([[470],{1716(a,e,t){t.r(e),t.d(e,{_pageData:()=>s,default:()=>n});var r=t(641);const s=JSON.parse('{"path":"/","title":"Smart Barcode Scan and Ordering","lang":"en-US","frontmatter":{"home":true,"title":"Smart Barcode Scan and Ordering","description":"Store-owner documentation for Smart Barcode Scan and Ordering — scan product and order barcodes from the WooCommerce admin, correct stock and pricing, build counter orders, and audit every scan.","heroImage":false,"heroText":"Smart Barcode Scan and Ordering","tagline":"Scan a barcode in the WooCommerce admin to pull up a product or an order, fix stock and prices on the spot, build a counter order, and keep a timestamped record of everything that was scanned.","actions":[{"text":"Start Here","link":"/smart-barcode-scan/overview","type":"primary"},{"text":"View Demo","link":"https://wpdemo.webkul.com/","type":"secondary"},{"text":"Buy Now","link":"https://codecanyon.net/item/barcode-mobile-scanner-for-woocommerce","type":"secondary"}],"footer":"© 2010-2026 Webkul. All Rights Reserved."},"git":{},"filePathRelative":"README.md"}'),d={name:"README.md"},n=(0,t(6262).A)(d,[["render",function(a,e,t,s,d,n){return(0,r.uX)(),(0,r.CE)("div",null,[...e[0]||(e[0]=[(0,r.Fv)('<div class="wk-stats-strip"><div class="wk-stats-heading"><h2>One console for scanning, stock corrections and counter sales</h2><p>Smart Barcode Scan and Ordering adds a single admin screen where a barcode is all your staff need to find a product, find an order, or ring up a sale.</p></div><div class="wk-stats-grid"><a href="/smart-barcode-scan-and-ordering/smart-barcode-scan/scanner-console.html" class="wk-stat wk-stat-accent"><div class="wk-stat-value">Scan</div><div class="wk-stat-label">Scanner Console</div><div class="wk-stat-sub">A focused scan box that accepts hardware-scanner input or typed codes, plus a Recent Scans panel showing the last five lookups.</div></a><a href="/smart-barcode-scan-and-ordering/smart-barcode-scan/product-scanning.html" class="wk-stat"><div class="wk-stat-value">Find</div><div class="wk-stat-label">Product &amp; Order Lookup</div><div class="wk-stat-sub">One code is matched against product ID, SKU, GTIN/UPC/EAN/ISBN, a custom meta field, product name and order ID.</div></a><a href="/smart-barcode-scan-and-ordering/smart-barcode-scan/inventory-management.html" class="wk-stat"><div class="wk-stat-value">Fix</div><div class="wk-stat-label">Inventory Quick Edit</div><div class="wk-stat-sub">Correct stock quantity, SKU, regular price, sale price, EAN code and the product image without leaving the popup.</div></a><a href="/smart-barcode-scan-and-ordering/smart-barcode-scan/create-order.html" class="wk-stat"><div class="wk-stat-value">Sell</div><div class="wk-stat-label">Create Order</div><div class="wk-stat-sub">Scan items into a cart, attach a customer, fill billing and shipping, calculate shipping, apply a coupon and create a real WooCommerce order.</div></a><a href="/smart-barcode-scan-and-ordering/smart-barcode-scan/order-status.html" class="wk-stat"><div class="wk-stat-value">Picked · Packed · Shipped</div><div class="wk-stat-label">Fulfilment Statuses</div><div class="wk-stat-sub">Three extra WooCommerce order statuses, advanced one stage per scan, with a tracking code required before an order can ship.</div></a><a href="/smart-barcode-scan-and-ordering/smart-barcode-scan/scan-logs.html" class="wk-stat"><div class="wk-stat-value">Audit</div><div class="wk-stat-label">Activity Logs</div><div class="wk-stat-sub">Every scan, product edit, order edit, order creation and settings change is recorded with a timestamp and the user who did it.</div></a><a href="/smart-barcode-scan-and-ordering/smart-barcode-scan/order-scanning.html" class="wk-stat"><div class="wk-stat-value">QR</div><div class="wk-stat-label">Order QR Labels</div><div class="wk-stat-sub">Generate, download or print a QR code for any order straight from the WooCommerce order list, one order at a time or in bulk.</div></a><a href="/smart-barcode-scan-and-ordering/smart-barcode-scan/scanner-settings.html" class="wk-stat"><div class="wk-stat-value">Tune</div><div class="wk-stat-label">Scanner Settings</div><div class="wk-stat-sub">Choose which fields a barcode is matched against, turn the scan beep on or off, auto-clear the input, and cap the log history.</div></a></div></div><div class="wk-new-features"><div class="wk-stats-heading"><h2>What you can do from the console</h2><p>Each workflow below is documented step by step, with screenshots taken from a live WooCommerce store.</p></div><div class="wk-features-grid"><div class="wk-feature-card"><div class="wk-feature-icon">🔍</div><h3>Scan a product and see everything about it</h3><p>Scan or type a barcode and the matching product opens in a popup with its image, type, status, SKU, prices, stock level and EAN code — all editable.</p><a href="/smart-barcode-scan-and-ordering/smart-barcode-scan/product-scanning.html" class="wk-feature-link">Read Product Scanning →</a></div><div class="wk-feature-card"><div class="wk-feature-icon">📦</div><h3>Correct stock during a count</h3><p>Adjust the stock quantity in the Inventory tab and save. Out-of-stock items are flagged, and the scanner refuses to add them to an order.</p><a href="/smart-barcode-scan-and-ordering/smart-barcode-scan/inventory-management.html" class="wk-feature-link">Read Inventory Management →</a></div><div class="wk-feature-card"><div class="wk-feature-icon">🧾</div><h3>Pull up an order by scanning it</h3><p>Scan an order QR label or type the order ID to see the customer, line items, totals breakdown, addresses and notes — and edit the status.</p><a href="/smart-barcode-scan-and-ordering/smart-barcode-scan/order-scanning.html" class="wk-feature-link">Read Order Scanning →</a></div><div class="wk-feature-card"><div class="wk-feature-icon">🛒</div><h3>Ring up a counter sale</h3><p>Scan items straight into a cart, adjust quantities within available stock, attach or create a customer, and create the order in one click.</p><a href="/smart-barcode-scan-and-ordering/smart-barcode-scan/create-order.html" class="wk-feature-link">Read Create Order →</a></div><div class="wk-feature-card"><div class="wk-feature-icon">👤</div><h3>Attach or register a customer</h3><p>Search existing users by name, username or email, or register a brand-new user without leaving the order screen.</p><a href="/smart-barcode-scan-and-ordering/smart-barcode-scan/customer-details.html" class="wk-feature-link">Read Customer Details →</a></div><div class="wk-feature-card"><div class="wk-feature-icon">🗂️</div><h3>Audit what was scanned</h3><p>Search, sort, paginate and delete scan history, and cap how many entries are kept — all from the Activity Logs tab.</p><a href="/smart-barcode-scan-and-ordering/smart-barcode-scan/scan-logs.html" class="wk-feature-link">Read Scan Logs →</a></div></div></div>',2)])])}]])}}]);